// ═══════════════════════════════════════════════════════════════════════════
//  PAID HOLIDAYS (hourly / residential staff)
//
//  Every hour worked on one of these dates, midnight to midnight, pays 1.5x
//  (see computePay in pay-engine.js). The list is generated by rule, so every
//  year is covered without anyone typing dates in.
//
//  It matches the company's 2026 holiday sheet for hourly/residential staff.
//  Days marked "Administration/Office" on that sheet are corporate-only and
//  are deliberately NOT here: Good Friday, and the observed Friday July 3rd.
//  Residential staff get the ACTUAL date of fixed holidays even on a weekend
//  (the 2026 sheet gives them Saturday July 4th).
//
//  Pure date math, no dependencies. Loaded before pay-engine.js, and
//  require()-able from the Node test suite.
// ═══════════════════════════════════════════════════════════════════════════
(function (root) {
  'use strict';

  const pad = n => String(n).padStart(2, '0');
  const ymd = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;
  const weekday = (y, m, d) => new Date(Date.UTC(y, m - 1, d)).getUTCDay();   // 0 = Sunday
  const mod = (n, m) => ((n % m) + m) % m;

  // The nth given weekday of a month (n = 1 for the first).
  function nthWeekday(y, m, wd, n) {
    return 1 + mod(wd - weekday(y, m, 1), 7) + 7 * (n - 1);
  }
  // The last given weekday of a month.
  function lastWeekday(y, m, wd) {
    const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
    return last - mod(weekday(y, m, last) - wd, 7);
  }
  // Easter Sunday: the Anonymous Gregorian computus. Returns [month, day].
  function easter(y) {
    const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4;
    const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
    const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4;
    const l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
    const x = h + l - 7 * m + 114;
    return [Math.floor(x / 31), (x % 31) + 1];
  }

  const byYear = new Map();
  function holidaysForYear(y) {
    y = Number(y);
    if (!Number.isInteger(y)) return [];
    if (!byYear.has(y)) {
      const [em, ed] = easter(y);
      byYear.set(y, [
        { date: ymd(y, 1, 1),                        name: "New Year's Day" },
        { date: ymd(y, 1, nthWeekday(y, 1, 1, 3)),   name: 'Martin Luther King Jr. Day' },
        { date: ymd(y, em, ed),                      name: 'Easter Sunday' },
        { date: ymd(y, 5, lastWeekday(y, 5, 1)),     name: 'Memorial Day' },
        { date: ymd(y, 6, 19),                       name: 'Juneteenth' },
        { date: ymd(y, 7, 4),                        name: 'Independence Day' },
        { date: ymd(y, 9, nthWeekday(y, 9, 1, 1)),   name: 'Labor Day' },
        { date: ymd(y, 11, nthWeekday(y, 11, 4, 4)), name: 'Thanksgiving' },
        { date: ymd(y, 12, 25),                      name: 'Christmas Day' },
      ]);
    }
    return byYear.get(y);
  }

  // The holiday on a YYYY-MM-DD date, or null.
  function holidayOn(dateStr) {
    const d = String(dateStr || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) return null;
    return holidaysForYear(d.slice(0, 4)).find(h => h.date === d) || null;
  }

  const Holidays = { holidaysForYear, holidayOn };

  root.Holidays = Holidays;
  if (typeof module !== 'undefined' && module.exports) module.exports = Holidays;
})(typeof globalThis !== 'undefined' ? globalThis : this);
